    for (int i = 0; i < 10_000; i++) {
        final int id = i;
        executor.submit(() -> {

            String result = httpClient.get("/api/data/" + id); // blocks the virtual thread, not the carrier

            process(result);
        });
    }
} // 10,000 concurrent tasks — far fewer than 10,000 OS threads doing the actual work

