// Thread pool (fixed OS threads) — concurrency via cooperative scheduling

// Many logical tasks run on far fewer real OS ("carrier") threads

vector<thread> carriers;
queue<function<void()>> tasks;
mutex mtx;
condition_variable cv;

for (int t = 0; t < 4; t++) {                 // just a handful of real OS threads
    carriers.emplace_back([&] {
        for (;;) {
            unique_lock<mutex> lock(mtx);
            cv.wait(lock, [] { return !tasks.empty(); });
            auto task = move(tasks.front());
            tasks.pop();
            lock.unlock();
            task();
        }
    });
}

for (int id = 0; id < 10000; id++) {
    lock_guard<mutex> lock(mtx);
    tasks.push([id] {

        string result = httpClient.get("/api/data/" + to_string(id)); // blocks this carrier thread briefly

        process(result);
    });
    cv.notify_one();
} // 10,000 concurrent tasks — far fewer than 10,000 OS threads doing the actual work

