// Parallel algorithm — splits the array across available cores

vector<long> data(100000000);
// ... fill data ...

long sum = reduce(execution::par, data.begin(), data.end(), 0L);
// splits work across the standard library's parallel execution backend

// On an 8-core machine, ~8 chunks computed simultaneously, then combined

// Equivalent explicit thread-based version for clarity:

long sumChunk(const vector<long>& data, size_t start, size_t end) {
    long total = 0;
    for (size_t i = start; i < end; i++) total += data[i];
    return total;
}

const int numThreads = 8;
size_t chunkSize = data.size() / numThreads;
vector<thread> workers;
vector<long> partialSums(numThreads, 0);

for (int t = 0; t < numThreads; t++) {
    size_t start = t * chunkSize;
    size_t end = (t == numThreads - 1) ? data.size() : start + chunkSize;
    workers.emplace_back([&, t, start, end] {
        partialSums[t] = sumChunk(data, start, end);   // runs on another core
    });
}
for (auto& w : workers) w.join();                       // wait for every chunk to finish

